// NOVEL (hand-authored) — not generated by CLI Printing Press.
// Recorded in .printing-press-patches/garmin-windowed-sync.json.
//
// `garmin-pp-cli history` — the windowed archive walk.
//
// Why this exists beside the generated `sync` rather than inside it: Garmin
// has no "give me everything since X" list endpoint. Its daily statistics come
// from range endpoints whose path IS the date range, capped at 28 days per
// request (verified live 2026-09-07 — see the per-series windowDays notes
// below), and its per-day endpoints answer for exactly one date. The press's
// profiler only marks an endpoint syncable when its path has no parameters,
// and its only temporal flag is --dates for a query parameter literally named
// dates/date_range/daterange, so none of these series can be expressed in the
// generated sync at all. This file owns the calendar walk; the generated sync
// keeps owning the flat resources it can genuinely enumerate.
//
// pp:data-source live
package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/mvanhorn/printing-press-library/library/health/garmin/internal/store"
	"github.com/spf13/cobra"
)

// garminGetter is the one method the walk needs from the API client. Typing
// against the interface rather than *client.Client is what lets the whole walk
// run against a fake in tests without a network call.
type garminGetter interface {
	Get(ctx context.Context, path string, params map[string]string) (json.RawMessage, error)
}

type garminSeriesKind int

const (
	// seriesWindowed pages history by date range: one request covers
	// windowDays calendar days.
	seriesWindowed garminSeriesKind = iota
	// seriesPerDay answers for exactly one date, so depth costs one request
	// per day and is bounded by --days rather than by the empty-window walk.
	seriesPerDay
	// seriesOffsetPaged is the activity feed: offset paging, no date range.
	seriesOffsetPaged
	// seriesPerParent fans out over ids already stored by another series.
	seriesPerParent
)

// garminRow is one extracted record: the id it is stored under and the
// calendar day it belongs to.
type garminRow struct {
	id   string
	day  civilDay
	data json.RawMessage
}

// garminSeries describes one archive series end to end.
type garminSeries struct {
	name     string
	kind     garminSeriesKind
	resource string // store resource_type this series writes
	summary  string

	// windowDays is the number of calendar days one request may cover.
	// Each value below was established by a live A/B request on 2026-09-07
	// against a populated account; a series whose larger window returned
	// HTTP 400 is pinned at Garmin's documented 28-day cap.
	windowDays int

	// needsDisplayName marks a path that embeds the account's Garmin
	// display name, which the walk resolves once per run.
	needsDisplayName bool

	// floor is the oldest day worth asking for. Garmin Connect predates
	// every consumer account in service, so this is a sanity stop, not a
	// data claim: a backward walk that somehow never sees an empty window
	// still terminates.
	floor civilDay

	// windowReq builds the request for a date range (seriesWindowed).
	windowReq func(w dayWindow, displayName string) (string, map[string]string)
	// dayReq builds the request for one date (seriesPerDay).
	dayReq func(d civilDay, displayName string) (string, map[string]string)
	// extract turns one response into rows. `requested` is the day or window
	// end that was asked for, used as the day of a payload that carries no
	// calendar field of its own.
	extract func(raw json.RawMessage, requested civilDay) ([]garminRow, error)
}

// garminHistoryFloor is the oldest date the walk will ever request. Garmin
// Connect launched in 2007; nothing older can exist in an account.
var garminHistoryFloor = mustParseCivilDay("2007-01-01")

// garminSeriesCatalog is every series the archive walk knows.
//
// Window sizes, verified live 2026-09-07 against a populated account:
//   - steps / sleep_stats / sleep_score → 28. A 364-day request returns
//     HTTP 400 with an error envelope; a 28-day request returns 200.
//   - resting_hr → 364 proven (a 364-day request returned 364 rows, a
//     28-day request 28).
//   - max_metrics → 364 proven (79 sparse rows across the year).
//   - intensity_minutes → 364 proven (53 weekly rows; this endpoint reports
//     one row per week, so 28 days would cost 13x the requests for the
//     same data).
func garminSeriesCatalog() []garminSeries {
	return []garminSeries{
		{
			name: "steps", kind: seriesWindowed, resource: "steps", windowDays: 28,
			summary: "Daily step count, goal and distance.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/usersummary-service/stats/steps/daily/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractDayList("calendarDate"),
		},
		{
			name: "sleep_stats", kind: seriesWindowed, resource: "sleep_stats", windowDays: 28,
			summary: "Per-night sleep summary: stage minutes, sleep score, overnight HRV and resting HR.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/sleep-service/stats/sleep/daily/" + w.start.String() + "/" + w.end.String(), nil
			},
			// This endpoint wraps its per-night rows in individualStats and
			// adds an overallStats block scoped to the requested window.
			// Only the per-night rows are archived: overallStats is a
			// derived view of the window we asked for, so storing it would
			// bake this run's arbitrary range into the archive.
			extract: extractNestedDayList([]string{"individualStats"}, "calendarDate"),
		},
		{
			name: "sleep_score", kind: seriesWindowed, resource: "sleep_score", windowDays: 28,
			summary: "Nightly sleep score.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/wellness-service/stats/daily/sleep/score/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractDayList("calendarDate"),
		},
		{
			name: "max_metrics", kind: seriesWindowed, resource: "max_metrics", windowDays: 364,
			summary: "VO2 max / MaxMET and fitness age, running and cycling.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/metrics-service/metrics/maxmet/daily/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractMaxMetrics,
		},
		{
			name: "intensity_minutes", kind: seriesWindowed, resource: "intensity_minutes", windowDays: 364,
			summary: "Weekly moderate and vigorous intensity minutes against the weekly goal.",
			floor:   garminHistoryFloor,
			windowReq: func(w dayWindow, _ string) (string, map[string]string) {
				return "/usersummary-service/stats/im/weekly/" + w.start.String() + "/" + w.end.String(), nil
			},
			extract: extractDayList("calendarDate"),
		},
		{
			name: "resting_hr", kind: seriesWindowed, resource: "resting_hr", windowDays: 364,
			summary:          "Daily resting heart rate (userstats metric 60).",
			floor:            garminHistoryFloor,
			needsDisplayName: true,
			windowReq: func(w dayWindow, displayName string) (string, map[string]string) {
				return "/userstats-service/wellness/daily/" + displayName, map[string]string{
					"fromDate":  w.start.String(),
					"untilDate": w.end.String(),
					"metricId":  "60",
				}
			},
			extract: extractNestedDayList([]string{"allMetrics", "metricsMap", "WELLNESS_RESTING_HEART_RATE"}, "calendarDate"),
		},
		{
			name: "activities", kind: seriesOffsetPaged, resource: "activities",
			summary: "The activity feed, newest first.",
			floor:   garminHistoryFloor,
		},
		{
			name: "activity_hr_zones", kind: seriesPerParent, resource: "activity_hr_zones",
			summary: "Seconds in each heart-rate zone, per activity.",
		},
		{
			name: "daily_summary", kind: seriesPerDay, resource: "daily_summary",
			summary:          "The full daily wellness summary: steps, calories, stress, body battery, respiration, SpO2.",
			needsDisplayName: true,
			floor:            garminHistoryFloor,
			dayReq: func(d civilDay, displayName string) (string, map[string]string) {
				return "/usersummary-service/usersummary/daily/" + displayName, map[string]string{"calendarDate": d.String()}
			},
			extract: extractSingleObject("calendarDate"),
		},
		{
			name: "sleep_detail", kind: seriesPerDay, resource: "sleep_detail",
			summary: "One night in full: sleep stages, overnight HR, HRV, stress, body battery and respiration series.",
			floor:   garminHistoryFloor,
			dayReq: func(d civilDay, _ string) (string, map[string]string) {
				return "/sleep-service/sleep/dailySleepData", map[string]string{"date": d.String()}
			},
			extract: extractSleepDetail,
		},
		{
			name: "daily_hr", kind: seriesPerDay, resource: "daily_hr",
			summary: "All-day heart-rate samples with the day's resting, min and max.",
			floor:   garminHistoryFloor,
			dayReq: func(d civilDay, _ string) (string, map[string]string) {
				return "/wellness-service/wellness/dailyHeartRate/", map[string]string{"date": d.String()}
			},
			extract: extractSingleObject("calendarDate"),
		},
		{
			name: "training_readiness", kind: seriesPerDay, resource: "training_readiness",
			summary: "Training readiness score and its contributing factors.",
			floor:   garminHistoryFloor,
			dayReq: func(d civilDay, _ string) (string, map[string]string) {
				return "/metrics-service/metrics/trainingreadiness/" + d.String(), nil
			},
			extract: extractDayListFallback("calendarDate"),
		},
	}
}

func garminSeriesByName() map[string]garminSeries {
	out := map[string]garminSeries{}
	for _, s := range garminSeriesCatalog() {
		out[s.name] = s
	}
	return out
}

func garminSeriesNames() []string {
	var out []string
	for _, s := range garminSeriesCatalog() {
		out = append(out, s.name)
	}
	sort.Strings(out)
	return out
}

// ---------------------------------------------------------------------------
// Response extraction
// ---------------------------------------------------------------------------

func jsonChild(raw json.RawMessage, key string) (json.RawMessage, bool) {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(raw, &obj); err != nil {
		return nil, false
	}
	child, ok := obj[key]
	if !ok || len(child) == 0 || string(child) == "null" {
		return nil, false
	}
	return child, true
}

func jsonAtPath(raw json.RawMessage, path []string) (json.RawMessage, bool) {
	current := raw
	for _, key := range path {
		child, ok := jsonChild(current, key)
		if !ok {
			return nil, false
		}
		current = child
	}
	return current, true
}

func jsonStringField(raw json.RawMessage, key string) string {
	child, ok := jsonChild(raw, key)
	if !ok {
		return ""
	}
	var s string
	if err := json.Unmarshal(child, &s); err != nil {
		return ""
	}
	return s
}

// dayFromValue accepts both "2026-09-07" and "2026-09-07 06:11:00", which is
// how Garmin spells a calendar date and a local timestamp respectively.
func dayFromValue(v string) (civilDay, bool) {
	if len(v) < 10 {
		return civilDay{}, false
	}
	d, err := parseCivilDay(v[:10])
	if err != nil {
		return civilDay{}, false
	}
	return d, true
}

// rowsFromList turns a JSON array into day-keyed rows. An item with no usable
// calendar field is dropped rather than stored under a guessed key; the caller
// sees the shortfall as a stored-vs-consumed gap and reports it.
func rowsFromList(list json.RawMessage, dayField string, fallback civilDay) ([]garminRow, error) {
	var items []json.RawMessage
	if err := json.Unmarshal(list, &items); err != nil {
		return nil, fmt.Errorf("expected a JSON array: %w", err)
	}
	rows := make([]garminRow, 0, len(items))
	for _, item := range items {
		day, ok := dayFromValue(jsonStringField(item, dayField))
		if !ok {
			if fallback.isZero() {
				continue
			}
			day = fallback
		}
		rows = append(rows, garminRow{id: day.String(), day: day, data: item})
	}
	return rows, nil
}

func extractDayList(dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, _ civilDay) ([]garminRow, error) {
		return rowsFromList(raw, dayField, civilDay{})
	}
}

// extractDayListFallback keys a row by the requested day when the payload
// carries no calendar field. Garmin's training-readiness response is a list
// whose shape varies with the device that produced it.
func extractDayListFallback(dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, requested civilDay) ([]garminRow, error) {
		return rowsFromList(raw, dayField, requested)
	}
}

func extractNestedDayList(path []string, dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, _ civilDay) ([]garminRow, error) {
		list, ok := jsonAtPath(raw, path)
		if !ok {
			// An absent branch is an empty window, not a malformed
			// response: Garmin omits the container for a range with no
			// readings.
			return nil, nil
		}
		return rowsFromList(list, dayField, civilDay{})
	}
}

func extractSingleObject(dayField string) func(json.RawMessage, civilDay) ([]garminRow, error) {
	return func(raw json.RawMessage, requested civilDay) ([]garminRow, error) {
		var obj map[string]json.RawMessage
		if err := json.Unmarshal(raw, &obj); err != nil {
			return nil, fmt.Errorf("expected a JSON object: %w", err)
		}
		if len(obj) == 0 {
			return nil, nil
		}
		day, ok := dayFromValue(jsonStringField(raw, dayField))
		if !ok {
			day = requested
		}
		if day.isZero() {
			return nil, nil
		}
		return []garminRow{{id: day.String(), day: day, data: raw}}, nil
	}
}

// extractSleepDetail keys a night by dailySleepDTO.calendarDate. A response
// whose dailySleepDTO is absent or null is a night with no recorded sleep —
// an empty result, not a failure.
func extractSleepDetail(raw json.RawMessage, requested civilDay) ([]garminRow, error) {
	dto, ok := jsonChild(raw, "dailySleepDTO")
	if !ok {
		return nil, nil
	}
	day, ok := dayFromValue(jsonStringField(dto, "calendarDate"))
	if !ok {
		day = requested
	}
	if day.isZero() {
		return nil, nil
	}
	return []garminRow{{id: day.String(), day: day, data: raw}}, nil
}

// extractMaxMetrics reads the calendar date out of whichever sport block the
// response carries. Garmin returns one entry per measured day with a `generic`
// (running) block, a `cycling` block, or both; days with no measurement are
// simply absent, which is why this series is sparse rather than daily.
func extractMaxMetrics(raw json.RawMessage, _ civilDay) ([]garminRow, error) {
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil, fmt.Errorf("expected a JSON array: %w", err)
	}
	rows := make([]garminRow, 0, len(items))
	for _, item := range items {
		var day civilDay
		for _, block := range []string{"generic", "cycling"} {
			child, ok := jsonChild(item, block)
			if !ok {
				continue
			}
			if d, parsed := dayFromValue(jsonStringField(child, "calendarDate")); parsed {
				day = d
				break
			}
		}
		if day.isZero() {
			continue
		}
		rows = append(rows, garminRow{id: day.String(), day: day, data: item})
	}
	return rows, nil
}

// ---------------------------------------------------------------------------
// Event emitter
// ---------------------------------------------------------------------------

// garminEmitter writes the same event vocabulary the generated sync uses —
// sync_start, sync_progress, sync_warning, sync_anomaly, sync_summary — so one
// consumer can read both. It never returns an error and never panics: a
// telemetry failure must not break the walk it observes, so every write is
// best-effort and every dynamic string goes through json.Marshal rather than
// being interpolated into a hand-built object.
type garminEmitter struct {
	w       io.Writer
	machine bool
}

func (e *garminEmitter) raw(line string) {
	if e == nil || e.w == nil {
		return
	}
	_, _ = io.WriteString(e.w, line+"\n")
}

func jsonString(s string) string {
	b, err := json.Marshal(s)
	if err != nil {
		return `""`
	}
	return string(b)
}

func (e *garminEmitter) human(format string, args ...any) {
	if e == nil || e.w == nil || e.machine {
		return
	}
	_, _ = fmt.Fprintf(e.w, format+"\n", args...)
}

func (e *garminEmitter) start(series string) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_start","resource":` + jsonString(series) + `}`)
		return
	}
	e.human("  %s ...", series)
}

func (e *garminEmitter) progress(series string, fetched int, window string) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_progress","resource":` + jsonString(series) +
			`,"fetched":` + strconv.Itoa(fetched) + `,"window":` + jsonString(window) + `}`)
		return
	}
}

func (e *garminEmitter) warn(series, reason, message string) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_warning","resource":` + jsonString(series) +
			`,"reason":` + jsonString(reason) + `,"message":` + jsonString(message) + `}`)
		return
	}
	e.human("  warning: %s: %s", series, message)
}

func (e *garminEmitter) anomaly(series, reason string, consumed, stored int) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(`{"event":"sync_anomaly","resource":` + jsonString(series) +
			`,"consumed":` + strconv.Itoa(consumed) +
			`,"stored":` + strconv.Itoa(stored) +
			`,"reason":` + jsonString(reason) + `}`)
		return
	}
	e.human("  anomaly: %s: %s (consumed %d, stored %d)", series, reason, consumed, stored)
}

func (e *garminEmitter) summary(totalRecords, resources, success, warned, errored int, d time.Duration) {
	if e == nil {
		return
	}
	if e.machine {
		e.raw(fmt.Sprintf(`{"event":"sync_summary","total_records":%d,"resources":%d,"success":%d,"warned":%d,"errored":%d,"duration_ms":%d}`,
			totalRecords, resources, success, warned, errored, d.Milliseconds()))
		return
	}
	e.human("\n%d rows across %d series in %s (%d ok, %d warned, %d errored)",
		totalRecords, resources, d.Round(time.Millisecond), success, warned, errored)
}

// ---------------------------------------------------------------------------
// Rate limiting and pacing
// ---------------------------------------------------------------------------

// errGarminRateLimited aborts the whole walk. Garmin's edge rate-limits by
// client shape, and our own research recorded 429s arriving in bursts, so the
// honest response to the first one is to stop asking — not to keep walking the
// remaining series and convert one 429 into a hundred.
var errGarminRateLimited = errors.New("garmin rate-limited the request; the walk stopped rather than retrying")

// errGarminWallOfFailures stops a run whose every request is failing.
//
// Observed live on 2026-09-07: a run whose credential had gone stale answered
// HTTP 403 to all 39 of its requests and emitted 39 separate warnings for one
// condition, then kept going. Neither 403 nor 401 carries a Retry-After or a
// rate-limit error type, so nothing in the per-call error path distinguishes
// "this request was refused" from "this client is finished". A whole run
// failing is a different fact from a request failing, and it deserves to be
// reported once and acted on immediately rather than restated per call.
var errGarminWallOfFailures = errors.New("every recent request failed; the walk stopped rather than continuing to ask")

// errGarminWindowDenied marks a window the backward walk was refused.
//
// Garmin answers HTTP 403 to a date range that reaches past the start of the
// account's own history — the same status it gives a credential that has gone
// stale, with nothing in the response to tell the two apart. Where the walk is
// does tell them apart. In the forward leg every window lies inside the
// account's lifetime, so a 403 there is a fault and counts toward the wall. In
// the backward leg it is the account's history start speaking, so it ends that
// series' walk the way an empty window does and never counts toward the wall.
//
// Live on 2026-09-12: `history --backfill` exited 5 because the first backward
// window of intensity_minutes answered 403 and ten refusals in a row across
// the ranged series read as a dead credential, so the run stopped before
// activities and every per-day series was attempted.
var errGarminWindowDenied = errors.New("garmin refused this window")

// defaultMaxConsecutiveFailures is how many failures in a row end a run. It is
// well above the handful a flaky connection produces and well below the
// hundreds a walk would otherwise spend proving the door is shut.
const defaultMaxConsecutiveFailures = 10

func isRateLimited(err error) bool {
	if err == nil {
		return false
	}
	return strings.Contains(err.Error(), "HTTP 429") || strings.Contains(err.Error(), "rate limited")
}

// isForbidden matches on the message the way isRateLimited does. The client
// rewraps an error whenever it masks credential text (internal/client
// maskedError), which drops the *client.APIError the status code lives on, so
// the status is only reliably readable as the text the error prints.
func isForbidden(err error) bool {
	if err == nil {
		return false
	}
	return strings.Contains(err.Error(), "HTTP 403")
}

// isWalkAborted reports the two conditions that end a whole run rather than
// one series: a rate limit, and a wall of consecutive failures.
func isWalkAborted(err error) bool {
	return errors.Is(err, errGarminRateLimited) || errors.Is(err, errGarminWallOfFailures)
}

// garminPacer spaces requests. The default 300 ms is the interval a live
// 94-window backfill walked at without a single 429 (N131 §9.2).
type garminPacer struct {
	delay time.Duration
	sleep func(time.Duration)
	first bool
}

func newGarminPacer(delay time.Duration, sleep func(time.Duration)) *garminPacer {
	if sleep == nil {
		sleep = time.Sleep
	}
	return &garminPacer{delay: delay, sleep: sleep, first: true}
}

func (p *garminPacer) wait() {
	if p == nil {
		return
	}
	if p.first {
		p.first = false
		return
	}
	if p.delay > 0 {
		p.sleep(p.delay)
	}
}

// ---------------------------------------------------------------------------
// The walk
// ---------------------------------------------------------------------------

type garminWalkOptions struct {
	series             []string
	days               int
	backfill           bool
	emptyWindowCeiling int
	delay              time.Duration
	maxPages           int
	maxDependents      int
	activityPageSize   int
	// maxConsecutiveFailures ends the run when this many calls fail in a
	// row. Zero means the default.
	maxConsecutiveFailures int
	strict                 bool
	dryRun                 bool
	now                    func() time.Time
	loc                    *time.Location
	sleep                  func(time.Duration)
}

type garminSeriesOutcome struct {
	series  string
	stored  int
	calls   int
	warned  bool
	errored bool
	err     error
}

type garminWalker struct {
	client      garminGetter
	db          *store.Store
	emit        *garminEmitter
	opts        garminWalkOptions
	pacer       *garminPacer
	displayName string
	nameLoaded  bool
	calls       int
	// consecutiveFailures counts failed calls since the last success,
	// across every series in the run.
	consecutiveFailures int
}

// get is the single choke point for every API call: it paces, counts, and
// converts a 429 into the sentinel that stops the run.
func (w *garminWalker) get(ctx context.Context, path string, params map[string]string) (json.RawMessage, error) {
	return w.getClassified(ctx, path, params, false)
}

// getHistoryEdge is get for the backward leg of a windowed walk, the one place
// a refused window is data rather than a fault. See errGarminWindowDenied.
func (w *garminWalker) getHistoryEdge(ctx context.Context, path string, params map[string]string) (json.RawMessage, error) {
	return w.getClassified(ctx, path, params, true)
}

func (w *garminWalker) getClassified(ctx context.Context, path string, params map[string]string, atHistoryEdge bool) (json.RawMessage, error) {
	w.pacer.wait()
	w.calls++
	data, err := w.client.Get(ctx, path, params)
	if isRateLimited(err) {
		w.consecutiveFailures++
		return nil, fmt.Errorf("%w: %v", errGarminRateLimited, err)
	}
	if err != nil {
		if atHistoryEdge && isForbidden(err) {
			// Neither counted nor cleared. Not counted, because a refusal
			// past the history start is not a failing client; not cleared,
			// because it is not a working one either, so a credential that
			// has genuinely died still hits the wall on the next request it
			// makes rather than walking every series to its ceiling first.
			return nil, fmt.Errorf("%w: %v", errGarminWindowDenied, err)
		}
		w.consecutiveFailures++
		limit := w.opts.maxConsecutiveFailures
		if limit < 1 {
			limit = defaultMaxConsecutiveFailures
		}
		if w.consecutiveFailures >= limit {
			return nil, fmt.Errorf("%w (%d in a row, most recently: %v)", errGarminWallOfFailures, w.consecutiveFailures, err)
		}
		return nil, err
	}
	w.consecutiveFailures = 0
	return data, err
}

// resolveDisplayName fetches the account's Garmin display name once per run.
// Three series embed it in their path; without it they cannot be requested.
func (w *garminWalker) resolveDisplayName(ctx context.Context) (string, error) {
	if w.nameLoaded {
		return w.displayName, nil
	}
	data, err := w.get(ctx, "/userprofile-service/socialProfile", nil)
	if err != nil {
		return "", err
	}
	name := jsonStringField(data, "displayName")
	if name == "" {
		return "", errors.New("social profile carried no displayName")
	}
	w.displayName = name
	w.nameLoaded = true
	return name, nil
}

// storeRows writes one window's rows and returns how many landed.
func (w *garminWalker) storeRows(series garminSeries, rows []garminRow) (int, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	keyed := make([]store.KeyedRow, 0, len(rows))
	for _, r := range rows {
		keyed = append(keyed, store.KeyedRow{ID: r.id, Data: r.data})
	}
	stored, skipped, err := w.db.UpsertKeyedBatch(series.resource, keyed)
	if err != nil {
		return stored, err
	}
	if skipped > 0 {
		w.emit.anomaly(series.name, "rows_without_usable_key", len(rows), stored)
	}
	return stored, nil
}

// mirrorSyncState copies a series' progress into the generated sync_state
// table so doctor, tail and anything else reading generated state sees the
// windowed series too. The authoritative bookmark stays in
// garmin_series_state; this is a projection, and a failure to write it is a
// warning rather than a lost window.
func (w *garminWalker) mirrorSyncState(series string, st store.GarminSeriesState) {
	if err := w.db.SaveSyncState(series, st.LastCompleteDay, st.TotalRows); err != nil {
		w.emit.warn(series, "sync_state_mirror_failed", "windowed state was saved but the generated sync_state row was not updated: "+err.Error())
	}
}

func dayRange(rows []garminRow) (oldest, newest civilDay) {
	for _, r := range rows {
		oldest = minDay(oldest, r.day)
		newest = maxDay(newest, r.day)
	}
	return oldest, newest
}

// walkWindowed runs one date-range series: forward to catch up, then, under
// --backfill, backwards until the empty-window ceiling.
func (w *garminWalker) walkWindowed(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}

	displayName := ""
	if s.needsDisplayName {
		displayName, err = w.resolveDisplayName(ctx)
		if err != nil {
			out.errored, out.err = true, err
			return out
		}
	}

	now := today(w.opts.now, w.opts.loc)
	ceiling := completeDayCeiling(now)

	// --- forward leg: from the day after the last complete day to today.
	from := now.addDays(-(w.opts.days - 1))
	if st.LastCompleteDay != "" {
		if last, parseErr := parseCivilDay(st.LastCompleteDay); parseErr == nil {
			from = last.addDays(1)
		}
	}
	if from.after(now) {
		// Already complete through yesterday; still refresh today, whose
		// row is partial by definition.
		from = now
	}

	newestStored := civilDay{}
	oldestStored := civilDay{}
	if st.EarliestDay != "" {
		if d, parseErr := parseCivilDay(st.EarliestDay); parseErr == nil {
			oldestStored = d
		}
	}

	// last_complete_day is a claim that EVERY day up to it is archived, so it
	// may only advance across an unbroken run of successful windows. Once one
	// window fails, later windows still fetch and store — their rows are real
	// — but the bookmark stops moving, so the next run re-requests the gap
	// instead of stepping over it forever.
	forwardBroken := false

	for _, win := range planForwardWindows(from, now, s.windowDays) {
		path, params := s.windowReq(win, displayName)
		data, callErr := w.get(ctx, path, params)
		if callErr != nil {
			if isWalkAborted(callErr) {
				out.errored, out.err = true, callErr
				return out
			}
			out.warned = true
			forwardBroken = true
			w.emit.warn(s.name, "window_fetch_failed", "window "+win.String()+": "+callErr.Error())
			continue
		}
		rows, exErr := s.extract(data, win.end)
		if exErr != nil {
			out.warned = true
			forwardBroken = true
			w.emit.anomaly(s.name, "window_shape_unrecognized", 0, 0)
			continue
		}
		stored, storeErr := w.storeRows(s, rows)
		if storeErr != nil {
			out.errored, out.err = true, storeErr
			return out
		}
		out.stored += stored
		st.TotalRows += stored
		o, n := dayRange(rows)
		oldestStored = minDay(oldestStored, o)
		newestStored = maxDay(newestStored, n)
		w.emit.progress(s.name, stored, win.String())

		// Checkpoint after every window, not at the end of the series: a
		// run killed mid-walk must resume where it stopped.
		if !forwardBroken {
			st.LastCompleteDay = minDay(maxDay(mustDay(st.LastCompleteDay), minDay(win.end, ceiling)), ceiling).String()
		}
		if oldestStored.isZero() {
			st.EarliestDay = ""
		} else {
			st.EarliestDay = oldestStored.String()
		}
		if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
			out.errored, out.err = true, saveErr
			return out
		}
	}

	// --- backward leg, only under --backfill.
	if w.opts.backfill {
		frontier := oldestStored
		if st.FrontierDay != "" {
			if d, parseErr := parseCivilDay(st.FrontierDay); parseErr == nil {
				frontier = minDay(frontier, d)
			}
		}
		if frontier.isZero() {
			frontier = from
		}
		empty := st.EmptyWindows
		if st.StopReason == "never_returned_data" && st.TotalRows > 0 {
			// The forward leg has since found rows, so the run of empty
			// windows that once read as "this account has no history"
			// no longer proves anything. Start the count again.
			empty = 0
		}
		everSaw := st.TotalRows > 0
		// A walk that already reached its ceiling stays there. Raising
		// --empty-window-ceiling resumes it deeper — from the same count,
		// so the flag means "this many consecutive empty windows in total",
		// not "this many more".
		if st.StopReason != "" && empty >= w.opts.emptyWindowCeiling {
			if st.StopReason == "never_returned_data" {
				out.warned = true
				w.emit.warn(s.name, "series_never_returned_data",
					"this series has never stored a row and its backward walk already reached the empty-window ceiling; earliest_day stays unset because an empty window cannot distinguish an account with no data from a request this tool got wrong")
			}
			w.mirrorSyncState(s.name, st)
			return out
		}
		// lastGoodWindow is the oldest window this run actually fetched, which
		// is what a refusal below it makes a claim about.
		lastGoodWindow := ""
		// denied counts refusals so a walk that ends at the floor or the
		// ceiling still says how many windows were refused rather than
		// reporting them as ordinary empty ones.
		denied := 0
		stop := ""
		for {
			win, ok := planBackwardWindow(frontier, s.floor, s.windowDays)
			if !ok {
				stop = "floor"
				break
			}
			path, params := s.windowReq(win, displayName)
			data, callErr := w.getHistoryEdge(ctx, path, params)
			if callErr != nil {
				if isWalkAborted(callErr) {
					out.errored, out.err = true, callErr
					return out
				}
				if errors.Is(callErr, errGarminWindowDenied) {
					// A refused window is an empty window: it counts toward
					// the ceiling and moves the frontier, so a re-run does
					// not re-probe it, and the walk ends at the ceiling
					// rather than at the wall.
					empty++
					denied++
					frontier = win.start
					st.FrontierDay = frontier.String()
					st.EmptyWindows = empty
					if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
						out.errored, out.err = true, saveErr
						return out
					}
					if empty >= w.opts.emptyWindowCeiling {
						stop = "window_denied_stop"
						break
					}
					continue
				}
				out.warned = true
				w.emit.warn(s.name, "window_fetch_failed", "window "+win.String()+": "+callErr.Error())
				stop = "interrupted"
				break
			}
			lastGoodWindow = win.String()
			rows, exErr := s.extract(data, win.end)
			if exErr != nil {
				out.warned = true
				w.emit.anomaly(s.name, "window_shape_unrecognized", 0, 0)
				stop = "interrupted"
				break
			}
			stored, storeErr := w.storeRows(s, rows)
			if storeErr != nil {
				out.errored, out.err = true, storeErr
				return out
			}
			out.stored += stored
			st.TotalRows += stored
			w.emit.progress(s.name, stored, win.String())

			if len(rows) == 0 {
				empty++
			} else {
				empty = 0
				everSaw = true
				o, _ := dayRange(rows)
				oldestStored = minDay(oldestStored, o)
			}
			frontier = win.start
			st.FrontierDay = frontier.String()
			st.EmptyWindows = empty
			if !oldestStored.isZero() {
				st.EarliestDay = oldestStored.String()
			}
			if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
				out.errored, out.err = true, saveErr
				return out
			}
			if empty >= w.opts.emptyWindowCeiling {
				stop = "empty_window_ceiling"
				break
			}
		}
		// A series that has never returned a single row proves nothing by
		// returning empty windows: the same silence covers "no wearable on
		// this account" and "this request shape is wrong". Say so, and do
		// not let the ceiling stand as a history claim.
		if !everSaw {
			stop = "never_returned_data"
			st.EarliestDay = ""
			out.warned = true
			w.emit.warn(s.name, "series_never_returned_data",
				"every window came back empty and this series has never stored a row; earliest_day was left unset because an empty window cannot distinguish an account with no data from a request this tool got wrong")
		}
		if denied > 0 {
			out.warned = true
			msg := fmt.Sprintf("Garmin refused %d window(s) before this point (HTTP 403); those ranges reach past the account's history start and will not be re-requested.", denied)
			if stop == "window_denied_stop" {
				msg = fmt.Sprintf("Garmin refused %d window(s) before this point (HTTP 403); the walk stopped at the account's history start.", denied)
			}
			if lastGoodWindow != "" {
				msg += " The earliest window it did fetch was " + lastGoodWindow + "."
			}
			w.emit.warn(s.name, "window_denied_stop", msg)
		}
		st.StopReason = stop
		if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
			out.errored, out.err = true, saveErr
			return out
		}
	}

	w.mirrorSyncState(s.name, st)
	return out
}

// mustDay parses a stored day string, returning the zero day for "" or junk.
// Stored state is our own writing, so a parse failure means a hand-edited
// database, not an API surprise: treat it as unset rather than fail the run.
func mustDay(s string) civilDay {
	if s == "" {
		return civilDay{}
	}
	d, err := parseCivilDay(s)
	if err != nil {
		return civilDay{}
	}
	return d
}

// walkPerDay runs one per-date series over the last --days days.
//
// These series are deliberately NOT backfilled to the empty-window ceiling.
// One request buys one day, and the payloads are large: a single night of
// sleep_detail measured 95 KB on a live account, and a full daily_hr day
// 11 KB. Walking a six-year account (the live account's steps reach
// 2020-07-06, 2 251 days) would cost 2 251 requests per series — about eleven
// minutes each at the 300 ms pacing — and roughly 215 MB of sleep detail
// alone. So depth here is an explicit --days choice a caller makes with that
// cost in view, and --backfill says so rather than silently doing it.
func (w *garminWalker) walkPerDay(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	displayName := ""
	if s.needsDisplayName {
		displayName, err = w.resolveDisplayName(ctx)
		if err != nil {
			out.errored, out.err = true, err
			return out
		}
	}
	if w.opts.backfill {
		out.warned = true
		w.emit.warn(s.name, "per_day_series_bounded_by_days",
			fmt.Sprintf("this series answers one calendar day per request, so --backfill does not walk it to the empty-window ceiling; it covered the last %d days. Raise --days to go deeper, knowing each extra day is one more request.", w.opts.days))
	}

	now := today(w.opts.now, w.opts.loc)
	ceiling := completeDayCeiling(now)
	from := now.addDays(-(w.opts.days - 1))
	if !s.floor.isZero() && from.before(s.floor) {
		from = s.floor
	}

	newest := civilDay{}
	oldest := mustDay(st.EarliestDay)
	for _, day := range enumerateDaysNewestFirst(from, now) {
		path, params := s.dayReq(day, displayName)
		data, callErr := w.get(ctx, path, params)
		if callErr != nil {
			if isWalkAborted(callErr) {
				out.errored, out.err = true, callErr
				return out
			}
			out.warned = true
			w.emit.warn(s.name, "day_fetch_failed", day.String()+": "+callErr.Error())
			continue
		}
		rows, exErr := s.extract(data, day)
		if exErr != nil {
			out.warned = true
			w.emit.anomaly(s.name, "day_shape_unrecognized", 0, 0)
			continue
		}
		stored, storeErr := w.storeRows(s, rows)
		if storeErr != nil {
			out.errored, out.err = true, storeErr
			return out
		}
		out.stored += stored
		st.TotalRows += stored
		if len(rows) > 0 {
			o, n := dayRange(rows)
			oldest = minDay(oldest, o)
			newest = maxDay(newest, n)
		}
		w.emit.progress(s.name, stored, day.String())
		// Newest-first means the bookmark can only advance once the whole
		// contiguous run down to `from` is done; checkpoint the frontier
		// instead, so a killed run resumes without re-fetching.
		st.FrontierDay = day.String()
		if !oldest.isZero() {
			st.EarliestDay = oldest.String()
		}
		if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
			out.errored, out.err = true, saveErr
			return out
		}
	}
	if !newest.isZero() {
		st.LastCompleteDay = minDay(newest, ceiling).String()
	}
	if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
		out.errored, out.err = true, saveErr
		return out
	}
	w.mirrorSyncState(s.name, st)
	return out
}

// walkActivities pages the activity feed.
//
// The wire parameter is `start`, not `offset`: verified live 2026-09-07 by
// requesting start=5 and offset=5 against the same account — start=5 returned
// the sixth-newest activity onward, offset=5 returned the same page as
// start=0, i.e. Garmin ignores `offset` entirely.
func (w *garminWalker) walkActivities(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	limit := w.opts.activityPageSize
	if limit < 1 {
		limit = 100
	}
	floor := civilDay{}
	if !w.opts.backfill {
		// Incremental: stop once the feed reaches a day already complete,
		// and on a first run stop at the --days horizon rather than pulling
		// the whole feed. Without that clamp a bare `history` would quietly
		// walk one series back to the account's first activity while every
		// other series covered --days, which is not what the flag says.
		horizon := today(w.opts.now, w.opts.loc).addDays(-(w.opts.days - 1))
		floor = maxDay(mustDay(st.LastCompleteDay), horizon)
	}

	newest := civilDay{}
	oldest := mustDay(st.EarliestDay)
	offset := 0
	pages := 0
	for {
		if w.opts.maxPages > 0 && pages >= w.opts.maxPages {
			out.warned = true
			w.emit.warn(s.name, "max_pages_cap_hit",
				fmt.Sprintf("reached --max-pages cap of %d; the feed may be truncated. Re-run with a higher --max-pages to go further back.", w.opts.maxPages))
			break
		}
		data, callErr := w.get(ctx, "/activitylist-service/activities/search/activities", map[string]string{
			"start": strconv.Itoa(offset),
			"limit": strconv.Itoa(limit),
		})
		if callErr != nil {
			if isWalkAborted(callErr) {
				out.errored, out.err = true, callErr
				return out
			}
			out.warned = true
			w.emit.warn(s.name, "page_fetch_failed", fmt.Sprintf("start=%d: %v", offset, callErr))
			break
		}
		var items []json.RawMessage
		if err := json.Unmarshal(data, &items); err != nil {
			out.warned = true
			w.emit.anomaly(s.name, "page_shape_unrecognized", 0, 0)
			break
		}
		pages++
		rows := make([]garminRow, 0, len(items))
		reachedFloor := false
		for _, item := range items {
			id := activityIDOf(item)
			if id == "" {
				continue
			}
			day, _ := dayFromValue(jsonStringField(item, "startTimeLocal"))
			if !floor.isZero() && !day.isZero() && day.before(floor) {
				reachedFloor = true
				continue
			}
			rows = append(rows, garminRow{id: id, day: day, data: item})
		}
		stored, storeErr := w.storeRows(s, rows)
		if storeErr != nil {
			out.errored, out.err = true, storeErr
			return out
		}
		out.stored += stored
		st.TotalRows += stored
		o, n := dayRange(rows)
		oldest = minDay(oldest, o)
		newest = maxDay(newest, n)
		w.emit.progress(s.name, stored, fmt.Sprintf("start=%d", offset))

		if !oldest.isZero() {
			st.EarliestDay = oldest.String()
		}
		st.FrontierDay = oldest.String()
		if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
			out.errored, out.err = true, saveErr
			return out
		}
		if reachedFloor || len(items) < limit {
			break
		}
		offset += limit
	}
	if !newest.isZero() {
		st.LastCompleteDay = minDay(newest, completeDayCeiling(today(w.opts.now, w.opts.loc))).String()
	}
	if w.opts.backfill {
		st.StopReason = "feed_exhausted"
	}
	if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
		out.errored, out.err = true, saveErr
		return out
	}
	w.mirrorSyncState(s.name, st)
	return out
}

func activityIDOf(item json.RawMessage) string {
	child, ok := jsonChild(item, "activityId")
	if !ok {
		return ""
	}
	var n json.Number
	if err := json.Unmarshal(child, &n); err == nil {
		return n.String()
	}
	var s string
	if err := json.Unmarshal(child, &s); err == nil {
		return s
	}
	return ""
}

// walkActivityHRZones fetches per-zone seconds for activities that do not
// have them yet. The payload is a bare five-element array with no id of its
// own, so it is wrapped with its activity id before storage — otherwise every
// activity's zones would collide under one key.
func (w *garminWalker) walkActivityHRZones(ctx context.Context, s garminSeries) garminSeriesOutcome {
	out := garminSeriesOutcome{series: s.name}
	parents, err := w.db.ResourceIDsNewestFirst("activities", 0)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	if len(parents) == 0 {
		w.emit.warn(s.name, "parent_table_empty",
			"no activities are stored yet, so there is nothing to fan out over; sync the activities series first")
		out.warned = true
		return out
	}
	missing, err := w.db.MissingResourceIDs(s.resource, parents)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	capped := false
	if w.opts.maxDependents > 0 && len(missing) > w.opts.maxDependents {
		missing = missing[:w.opts.maxDependents]
		capped = true
	}
	st, err := w.db.GetGarminSeriesState(s.name)
	if err != nil {
		out.errored, out.err = true, err
		return out
	}
	for _, id := range missing {
		data, callErr := w.get(ctx, "/activity-service/activity/"+id+"/hrTimeInZones", nil)
		if callErr != nil {
			if isWalkAborted(callErr) {
				out.errored, out.err = true, callErr
				return out
			}
			out.warned = true
			w.emit.warn(s.name, "per_parent_fetch_failed", "activity "+id+": "+callErr.Error())
			continue
		}
		var zones []json.RawMessage
		if err := json.Unmarshal(data, &zones); err != nil {
			out.warned = true
			w.emit.anomaly(s.name, "per_parent_shape_unrecognized", 0, 0)
			continue
		}
		wrapped, err := json.Marshal(map[string]any{
			"activityId":      id,
			"hrTimeInZones":   json.RawMessage(data),
			"zoneCount":       len(zones),
			"garminWrappedBy": "history",
		})
		if err != nil {
			out.warned = true
			w.emit.anomaly(s.name, "per_parent_wrap_failed", 1, 0)
			continue
		}
		stored, storeErr := w.storeRows(s, []garminRow{{id: id, data: wrapped}})
		if storeErr != nil {
			out.errored, out.err = true, storeErr
			return out
		}
		out.stored += stored
		st.TotalRows += stored
		if saveErr := w.db.SaveGarminSeriesState(st); saveErr != nil {
			out.errored, out.err = true, saveErr
			return out
		}
	}
	if capped {
		out.warned = true
		w.emit.warn(s.name, "max_dependents_cap_hit",
			fmt.Sprintf("stopped after %d activities; re-run to continue, or raise --max-dependents", w.opts.maxDependents))
	}
	w.emit.progress(s.name, out.stored, fmt.Sprintf("%d pending", len(missing)))
	w.mirrorSyncState(s.name, st)
	return out
}

func (w *garminWalker) walkSeries(ctx context.Context, s garminSeries) garminSeriesOutcome {
	var out garminSeriesOutcome
	switch s.kind {
	case seriesWindowed:
		// walkWindowed carries its own never-returned-data reporting,
		// because there the silence also decides whether earliest_day may
		// be stamped.
		return w.walkWindowed(ctx, s)
	case seriesPerDay:
		out = w.walkPerDay(ctx, s)
	case seriesOffsetPaged:
		out = w.walkActivities(ctx, s)
	case seriesPerParent:
		out = w.walkActivityHRZones(ctx, s)
	default:
		return garminSeriesOutcome{series: s.name, warned: true}
	}
	// A series that has still never stored a row after a completed run is
	// reporting a zero nobody has proven. Say so: the same silence covers
	// "this account has no such data" and "this tool asked wrong", and a
	// caller reading an empty table deserves to know which question is open.
	if !out.errored {
		if st, err := w.db.GetGarminSeriesState(s.name); err == nil && st.TotalRows == 0 {
			out.warned = true
			w.emit.warn(s.name, "series_returned_no_rows",
				"this series has completed a run without ever storing a row; that is either an account with no such data or a request shape this tool has wrong, and an empty response cannot tell them apart")
		}
	}
	return out
}

// ---------------------------------------------------------------------------
// Plan (used by --dry-run and by the performance test)
// ---------------------------------------------------------------------------

// garminPlanEntry is what one series will cost, in requests, for a given
// forward range. It exists so the shape of the walk can be asserted without
// making a single call.
type garminPlanEntry struct {
	Series     string `json:"series"`
	Kind       string `json:"kind"`
	Requests   int    `json:"requests"`
	WindowDays int    `json:"window_days,omitempty"`
	Range      string `json:"range,omitempty"`
	Note       string `json:"note,omitempty"`
}

func kindName(k garminSeriesKind) string {
	switch k {
	case seriesWindowed:
		return "windowed"
	case seriesPerDay:
		return "per_day"
	case seriesOffsetPaged:
		return "offset_paged"
	case seriesPerParent:
		return "per_parent"
	}
	return "unknown"
}

// planGarminForwardWork reports the request cost of a forward (incremental)
// run covering the last `days` days ending at `end`.
func planGarminForwardWork(selected []garminSeries, end civilDay, days int) []garminPlanEntry {
	from := end.addDays(-(days - 1))
	out := make([]garminPlanEntry, 0, len(selected))
	for _, s := range selected {
		entry := garminPlanEntry{Series: s.name, Kind: kindName(s.kind)}
		switch s.kind {
		case seriesWindowed:
			windows := planForwardWindows(from, end, s.windowDays)
			entry.Requests = len(windows)
			entry.WindowDays = s.windowDays
			entry.Range = from.String() + ".." + end.String()
		case seriesPerDay:
			entry.Requests = len(enumerateDaysNewestFirst(from, end))
			entry.Range = from.String() + ".." + end.String()
			entry.Note = "one request per calendar day"
		case seriesOffsetPaged:
			entry.Requests = -1
			entry.Note = "pages until the feed reaches an already-complete day"
		case seriesPerParent:
			entry.Requests = -1
			entry.Note = "one request per activity that has no zone row yet"
		}
		out = append(out, entry)
	}
	return out
}

// ---------------------------------------------------------------------------
// Command
// ---------------------------------------------------------------------------

func newGarminHistoryCmd(flags *rootFlags) *cobra.Command {
	var (
		seriesFlag             []string
		days                   int
		backfill               bool
		emptyWindowCeiling     int
		delay                  time.Duration
		maxPages               int
		maxDependents          int
		pageSize               int
		strict                 bool
		dbPath                 string
		maxConsecutiveFailures int
	)

	cmd := &cobra.Command{
		Use:   "history",
		Short: "Walk Garmin's date-ranged daily series into the local archive",
		Long: `Build and maintain the local archive of Garmin's daily series.

Garmin serves daily statistics from date-range endpoints that accept at most
28 calendar days per request, and per-day endpoints that answer for exactly
one date. Neither shape can be enumerated by the generated ` + "`sync`" + `, so this
command owns the calendar walk: it fetches forward from wherever each series
left off, and under --backfill walks backwards a window at a time until it
has seen enough consecutive empty windows to conclude the account's history
has run out.

State is per series: the newest day known complete, the oldest day the archive
reaches, the oldest day probed, and why the last backward walk stopped. Today
is never recorded as complete, because the day is still accruing.

Series that answer one day per request (daily_summary, sleep_detail, daily_hr,
training_readiness) are bounded by --days rather than walked to the ceiling;
one night of sleep_detail is roughly 95 KB, so deep history there is an
explicit choice, not a default.`,
		Example: `  # Catch up every series since the last run
  garmin-pp-cli history

  # First run on a new account: walk the full history of the ranged series
  garmin-pp-cli history --backfill

  # Just the last eight weeks of the heavy per-day series
  garmin-pp-cli history --series daily_summary,sleep_detail,daily_hr --days 56

  # See what a run would cost without making a call
  garmin-pp-cli history --backfill --dry-run --json`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) > 0 {
				return usageErr(fmt.Errorf("history takes no positional arguments; use --series to choose series"))
			}
			if days < 1 {
				return usageErr(fmt.Errorf("--days must be at least 1"))
			}
			if emptyWindowCeiling < 1 {
				return usageErr(fmt.Errorf("--empty-window-ceiling must be at least 1"))
			}
			if delay < 0 {
				return usageErr(fmt.Errorf("--delay cannot be negative"))
			}

			catalog := garminSeriesByName()
			var selected []garminSeries
			if len(seriesFlag) == 0 {
				selected = garminSeriesCatalog()
			} else {
				for _, raw := range seriesFlag {
					for _, name := range strings.Split(raw, ",") {
						name = strings.TrimSpace(name)
						if name == "" {
							continue
						}
						s, ok := catalog[name]
						if !ok {
							return usageErr(fmt.Errorf("unknown series %q; known series: %s", name, strings.Join(garminSeriesNames(), ", ")))
						}
						selected = append(selected, s)
					}
				}
			}
			if len(selected) == 0 {
				return usageErr(fmt.Errorf("no series selected"))
			}

			machine := wantsMachineOutput(flags)
			eventWriter := cmd.OutOrStdout()
			if machine {
				eventWriter = cmd.ErrOrStderr()
			}
			emit := &garminEmitter{w: eventWriter, machine: machine}

			now := time.Now
			end := today(now, time.Local)

			if flags.dryRun {
				plan := planGarminForwardWork(selected, end, days)
				if flags.asJSON {
					return flags.printJSON(cmd, map[string]any{
						"plan":                 plan,
						"days":                 days,
						"backfill":             backfill,
						"empty_window_ceiling": emptyWindowCeiling,
						"delay_ms":             delay.Milliseconds(),
					})
				}
				rows := make([][]string, 0, len(plan))
				for _, p := range plan {
					requests := strconv.Itoa(p.Requests)
					if p.Requests < 0 {
						requests = "variable"
					}
					rows = append(rows, []string{p.Series, p.Kind, requests, p.Range, p.Note})
				}
				return flags.printTable(cmd, []string{"SERIES", "KIND", "REQUESTS", "RANGE", "NOTE"}, rows)
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c.NoCache = true

			if dbPath == "" {
				dbPath = garminArchivePath(cmd.Context(), cmd.ErrOrStderr())
			}
			db, err := store.OpenWithContext(cmd.Context(), dbPath)
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureGarminSeriesState(); err != nil {
				return err
			}

			walker := &garminWalker{
				client: c,
				db:     db,
				emit:   emit,
				opts: garminWalkOptions{
					days:                   days,
					backfill:               backfill,
					emptyWindowCeiling:     emptyWindowCeiling,
					delay:                  delay,
					maxPages:               maxPages,
					maxDependents:          maxDependents,
					activityPageSize:       pageSize,
					strict:                 strict,
					maxConsecutiveFailures: maxConsecutiveFailures,
					now:                    now,
					loc:                    time.Local,
				},
				pacer: newGarminPacer(delay, nil),
			}

			started := time.Now()
			var total, success, warned, errored int
			var firstErr error
			for _, s := range selected {
				emit.start(s.name)
				outcome := walker.walkSeries(cmd.Context(), s)
				total += outcome.stored
				switch {
				case outcome.errored:
					errored++
					if firstErr == nil {
						firstErr = fmt.Errorf("%s: %w", outcome.series, outcome.err)
					}
					emit.warn(s.name, "series_failed", outcome.err.Error())
				case outcome.warned:
					warned++
				default:
					success++
				}
				if outcome.errored && errors.Is(outcome.err, errGarminRateLimited) {
					emit.warn(s.name, "rate_limited_fail_fast",
						"Garmin rate-limited this account; the remaining series were not attempted. Wait before re-running.")
					emit.summary(total, len(selected), success, warned, errored, time.Since(started))
					return rateLimitErr(firstErr)
				}
				if outcome.errored && errors.Is(outcome.err, errGarminWallOfFailures) {
					emit.warn(s.name, "consecutive_failures_abort",
						fmt.Sprintf("%d requests failed in a row, so the remaining series were not attempted. A whole run failing usually means the credential stopped being accepted or the service is refusing this client, not that these particular requests were unlucky. Run `garmin-pp-cli auth status`, then re-run.", maxConsecutiveFailures))
					emit.summary(total, len(selected), success, warned, errored, time.Since(started))
					return apiErr(firstErr)
				}
			}
			emit.summary(total, len(selected), success, warned, errored, time.Since(started))

			if errored > 0 && strict {
				return apiErr(firstErr)
			}
			return nil
		},
	}

	cmd.Flags().StringSliceVar(&seriesFlag, "series", nil,
		"Series to walk (comma-separated). Default: every series. Known: "+strings.Join(garminSeriesNames(), ", "))
	cmd.Flags().IntVar(&days, "days", 28,
		"How many recent days a forward run covers, and the full depth of the one-request-per-day series.")
	cmd.Flags().BoolVar(&backfill, "backfill", false,
		"Also walk the date-ranged series backwards through history until the empty-window ceiling is reached.")
	cmd.Flags().IntVar(&emptyWindowCeiling, "empty-window-ceiling", 13,
		"How many consecutive empty windows end a backward walk. 13 windows of 28 days is about a year of silence.")
	cmd.Flags().DurationVar(&delay, "delay", 300*time.Millisecond,
		"Pause between API calls. The default paced a 94-window live backfill without a single 429.")
	cmd.Flags().IntVar(&maxPages, "max-pages", 0,
		"Cap on activity-feed pages (0 = until the feed ends or reaches an already-complete day).")
	cmd.Flags().IntVar(&maxDependents, "max-dependents", 500,
		"Cap on per-activity heart-rate-zone fetches in one run (0 = no cap).")
	cmd.Flags().IntVar(&pageSize, "page-size", 100, "Activity-feed page size.")
	cmd.Flags().BoolVar(&strict, "strict", false, "Exit non-zero when any series fails. By default a failed series warns and the run continues.")
	cmd.Flags().IntVar(&maxConsecutiveFailures, "max-consecutive-failures", defaultMaxConsecutiveFailures,
		"End the run when this many requests fail in a row. A whole run failing usually means the credential stopped being accepted or the service is refusing this client, not that these requests were unlucky.")
	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path. The default is this home's data directory data.db, which is named for the home rather than for the credential in use, so a token refresh never orphans it; pass --db to read or write a different file.")

	return cmd
}

// ---------------------------------------------------------------------------
// Archive path
// ---------------------------------------------------------------------------

// garminArchiveName is the one archive file name this tool's design names:
// N131 §3, "SQLite archive at <data>/data.db".
const garminArchiveName = "data.db"

// garminScopedArchivePattern matches the token-scoped archive name the
// generated resolver invents, `data-<sha256(auth header)[:12]>.db`.
var garminScopedArchivePattern = regexp.MustCompile(
	`^data-[0-9a-f]{` + strconv.Itoa(defaultDBScopeHashLen) + `}\.db$`)

// garminArchivePath resolves the archive the novel commands read and write,
// and it is deliberately not the generated resolver.
//
// The generated defaultDBPathInDir names the archive after a hash of the
// current Authorization header, so a home's archive is scoped to the
// credential in use. Garmin's DI chain rotates its refresh token on every
// refresh and its access token roughly daily, so that name changes under a
// daily sync and every rotation orphans the previous file: rows already walked
// stop being visible and the next `history` re-walks years of history into a
// new file. Nothing about a Garmin home needs that scoping — the design binds
// one account to one home (N131 §2 Q3), so the home already is the isolation
// boundary and the archive can carry the plain name §3 gives it.
//
// The fix has to survive the generated commands too, because `sync`,
// `analytics` and `search` resolve through defaultDBPath and must not end up
// on a different file from `history` and `insights`. That is why this resolver
// does not merely return a different path: it makes the unscoped file exist.
// The generated resolver prefers a scoped file when one is present and falls
// through to an existing unscoped file otherwise, so once the scoped file is
// gone and data.db is there, every generated command follows.
//
// dir comes from the generated resolver's own answer rather than from a second
// call to cliutil.DataDir, so the pin lands in exactly the directory the
// generated resolver reads, including on its fallback branches.
func garminArchivePath(ctx context.Context, warn io.Writer) string {
	generated := defaultDBPath("garmin-pp-cli")
	dir := filepath.Dir(generated)
	unscoped := filepath.Join(dir, garminArchiveName)

	scoped := garminScopedArchives(dir)

	if _, err := os.Stat(unscoped); err == nil {
		if len(scoped) > 0 {
			fmt.Fprintf(warn,
				"warning: %s holds both %s and %d token-scoped archive(s) (%s).\n"+
					"  history and insights use %s. The generated sync, analytics and search prefer the\n"+
					"  scoped file, so they are writing a different archive: move or delete the scoped\n"+
					"  file(s), or pass --db to pin one file explicitly.\n",
				dir, garminArchiveName, len(scoped), strings.Join(scoped, ", "), garminArchiveName)
		}
		return unscoped
	} else if !os.IsNotExist(err) {
		// The directory is unreadable or something stranger; guessing here
		// would be worse than deferring to the generated answer.
		return generated
	}

	switch len(scoped) {
	case 0:
		if err := garminPinArchive(unscoped); err != nil {
			fmt.Fprintf(warn, "warning: could not create %s (%v); using %s\n", unscoped, err, generated)
			return generated
		}
	case 1:
		if err := garminMigrateScopedArchive(ctx, filepath.Join(dir, scoped[0]), unscoped); err != nil {
			fmt.Fprintf(warn, "warning: could not rename %s to %s (%v); using it where it is\n",
				scoped[0], garminArchiveName, err)
			return filepath.Join(dir, scoped[0])
		}
		fmt.Fprintf(warn,
			"notice: renamed the token-scoped archive %s to %s in %s.\n"+
				"  The archive is now named for this home, not for the credential, so a token refresh\n"+
				"  no longer orphans it.\n",
			scoped[0], garminArchiveName, dir)
	default:
		// Two or more scoped files means two credentials have already written
		// separate archives here. Picking one would silently discard the
		// other, so this starts a clean unscoped archive and names them all.
		if err := garminPinArchive(unscoped); err != nil {
			fmt.Fprintf(warn, "warning: could not create %s (%v); using %s\n", unscoped, err, generated)
			return generated
		}
		fmt.Fprintf(warn,
			"warning: %s holds %d token-scoped archives (%s) and no %s, so none of them could be\n"+
				"  renamed without discarding the others. Started an empty %s; pass --db to read one of\n"+
				"  the existing files instead.\n",
			dir, len(scoped), strings.Join(scoped, ", "), garminArchiveName, garminArchiveName)
	}
	return unscoped
}

// garminScopedArchives lists the token-scoped archive names in dir, sorted.
func garminScopedArchives(dir string) []string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var found []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if garminScopedArchivePattern.MatchString(e.Name()) {
			found = append(found, e.Name())
		}
	}
	sort.Strings(found)
	return found
}

// garminPinArchive creates an empty archive file so the generated resolver's
// "an unscoped archive exists" branch takes over for the generated commands
// too. A zero-byte file is a valid empty SQLite database, so the first open
// migrates it normally. Permissions match what the store enforces afterwards.
func garminPinArchive(path string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600) // #nosec G304 -- app-derived archive path: garminArchivePath's own <data-dir>/data.db (--db never reaches here).
	if err != nil {
		return err
	}
	return f.Close()
}

// garminMigrateScopedArchive renames a token-scoped archive to the unscoped
// name so its rows are not orphaned.
//
// Deviation from "one atomic rename": the store opens in WAL mode, so a
// -wal/-shm pair can sit beside the archive, and renaming the main file alone
// would strand the committed transactions in the stale WAL. Opening and
// closing the store first checkpoints the WAL back into the main file, after
// which the single rename carries everything. Any sidecar SQLite still leaves
// behind is renamed alongside rather than deleted.
func garminMigrateScopedArchive(ctx context.Context, scoped, unscoped string) error {
	if _, err := os.Stat(scoped + "-wal"); err == nil {
		if db, openErr := store.OpenWithContext(ctx, scoped); openErr == nil {
			_ = db.Close()
		}
	}
	if err := os.Rename(scoped, unscoped); err != nil {
		return err
	}
	for _, suffix := range []string{"-wal", "-shm"} {
		if _, err := os.Stat(scoped + suffix); err == nil {
			_ = os.Rename(scoped+suffix, unscoped+suffix)
		}
	}
	return nil
}
